<?php
chdir(dirname(__DIR__));

session_start();require_once 'dbconn.php';require_once 'includes/functions.php';requireLogin();$role=$_SESSION['role'];$params=[];$where="sy.year_status='Completed'";
if($role==='Student'){$q=$pdo->prepare("SELECT s.student_lrn FROM students s WHERE s.user_id=?");$q->execute([$_SESSION['user_id']]);$lrn=$q->fetchColumn();$where.=' AND e.student_lrn=?';$params[]=$lrn;}
elseif(in_array($role,['Subject Teacher','Teacher Adviser'],true)){$q=$pdo->prepare('SELECT teacher_id FROM teachers WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$tid=(int)$q->fetchColumn();$where.=' AND (EXISTS (SELECT 1 FROM section_subjects ss2 WHERE ss2.section_id=cs.section_id AND ss2.teacher_id=?) OR cs.adviser_teacher_id=?)';$params[]=$tid;$params[]=$tid;}
$sql="SELECT sy.school_year_name,e.grade_level,cs.section_name,e.student_lrn,CONCAT_WS(' ',st.first_name,st.middle_name,st.last_name) student_name,e.enrollment_status,e.final_result FROM enrollments e JOIN school_years sy ON sy.school_year_id=e.school_year_id LEFT JOIN class_sections cs ON cs.section_id=e.section_id JOIN students st ON st.student_lrn=e.student_lrn WHERE $where ORDER BY sy.school_year_name DESC,e.grade_level,cs.section_name,st.last_name,st.first_name";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();$groups=[];foreach($rows as $r)$groups[$r['school_year_name']][$r['grade_level']][$r['section_name']??'Unassigned'][]=$r;require 'includes/header.php';?><div class="page-heading"><div><h1>Past Records</h1></div><button type="button" class="btn btn-outline-primary print-action" onclick="window.print()" aria-label="Print this page" title="Print this page">🖨️ Print</button></div><?php if(!$groups):?><div class="card p-3">No completed school-year records yet.</div><?php else:foreach($groups as $year=>$grades):?><details class="card p-3 mb-3"><summary class="h5 mb-0"><?=e($year)?></summary><div class="mt-3"><?php foreach($grades as $grade=>$sections):?><h5 class="mt-3"><?=e($grade)?></h5><?php foreach($sections as $section=>$students):?><h6><?=e($section)?></h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>#</th><th>LRN</th><th>Student</th><th>Enrollment</th><th>Result</th></tr></thead><tbody><?php foreach($students as $i=>$st):?><tr><td><?=$i+1?></td><td><?=e($st['student_lrn'])?></td><td><?=e($st['student_name'])?></td><td><?=e($st['enrollment_status'])?></td><td><?=e($st['final_result']??'')?></td></tr><?php endforeach;?></tbody></table></div><?php endforeach;endforeach;?></div></details><?php endforeach;endif;?><?php require 'includes/footer.php';?>
